E["quest:1444"] = {t="quest",n="Return to Fel'Zerul",z="hinterlands",s="An exiled Atal'ai in the Hinterlands has looked over the artifacts brought to them and calls them harmless. They have darker worries about Jammal'an the Prophet, and Fel'zerul in Stonard is to hear them.",h="An exiled Atal'ai in the Hinterlands has looked over the artifacts brought to them and calls them harmless.",sec={{t="Words from an Exile",b="The Atal'ai Exile once held Jammal'an the Prophet to be a worthy high priest. But the prophet's unyielding faith in the prophecy may doom the Atal'ai, if it has not done so already. Speaking up got the exile branded an infidel and driven out of the Temple of Atal'Hakkar. The artifacts you brought pose no harm. What frightens the exile is the chance that Jammal'an has found the right fetish enchantment for the summoning ritual, which would put the world in great peril. Fel'zerul in Stonard waits to hear what was learned.",sp=0}},faq={{q="Where must I go to speak with Fel'zerul?",a="Fel'zerul is in Stonard.",al={"fel'zerul location","where is fel'zerul","turn in return to fel'zerul"}},{q="Why was the Atal'ai Exile banished?",a="The exile spoke out about Jammal'an the Prophet's unyielding faith in his prophecy, which they believe will destroy the Atal'ai. For voicing those concerns they were called an infidel and driven out of the Temple of Atal'Hakkar.",al={"why was atal'ai exile banished","why is the exile in hinterlands","atal'ai exile backstory"}},{q="Are the artifacts brought to the exile dangerous?",a="The exile says they are harmless. The worry is the summoning ritual, and whether Jammal'an has found the right fetish enchantment for it.",al={"are the artifacts harmful","fetish artifacts danger"}}},kw={"atal'ai exile","fel'zerul","hinterlands","jammal'an","stonard","summoning ritual","temple of atal'hakkar"},rel={"npc:fel-zerul","subzone:stonard","subzone:temple-of-atal-hakkar","zone:hinterlands"},m={start="Atal'ai Exile",["end"]="Fel'zerul",level="44",faction="Horde",id=1444},src={"Wowpedia: Return to Fel'Zerul"}}
E["quest:1450"] = {t="quest",n="Gryphon Master Talonaxe",z="hinterlands",s="Falstad Wildhammer will not be drawn on who once flew with an old Explorers' League friend, and sends you off to ask the gryphon master. Gryphon Master Talonaxe waits inside the Aerie Peak Aviary.",h="Falstad Wildhammer will not be drawn on who once flew with an old Explorers' League friend, and sends you off...",sec={{t="Sent Away",b="Falstad Wildhammer has no patience for someone sent on behalf of an old Explorers' League member. Who that friend once flew with is not something Falstad knows, and the flight assignments are for the gryphon master to answer. Gryphon Master Talonaxe is to be found inside the Aerie Peak Aviary, and lingering around Falstad will earn real work.",sp=0},{t="What Talonaxe Remembers",b="Talonaxe remembers sending a gryphon rider to help Brohann Caskbelly, and has long had a soft spot for the Explorers' League, since Talonaxe's father helped with the first excavation team to find Uldaman. The rider was Rhapsody Shindigger, whom Talonaxe thought the best at the time.",sp=1}},faq={{q="Why does Falstad Wildhammer send you to Talonaxe?",a="Falstad does not know who the Explorers' League friend flew with, and points to the gryphon master as the one who handles flight assignments.",al={"why see talonaxe","falstad sending away","who is talonaxe"}},{q="Where is Gryphon Master Talonaxe located?",a="Gryphon Master Talonaxe is inside the Aerie Peak Aviary.",al={"where is talonaxe","talonaxe location","aerie peak aviary"}}},kw={"aerie peak","aviary","brohann caskbelly","explorers league","falstad wildhammer","gryphon master talonaxe","rhapsody shindigger","uldaman"},rel={"quest:1451","topic:explorers-league","subzone:uldaman","zone:hinterlands"},m={start="Falstad Wildhammer",["end"]="Gryphon Master Talonaxe",level="43",faction="Alliance",id=1450},src={"Wowpedia: Gryphon Master Talonaxe (quest)"}}
E["quest:1451"] = {t="quest",n="Rhapsody Shindigger",z="hinterlands",s="Gryphon Master Talonaxe tells of Rhapsody Shindigger, once the finest flyer at the aviary, who took so keenly to liquor that Rhapsody had to be let go. Talonaxe has heard that Rhapsody now keeps a brewing camp east of the aviary, in the Hinterlands.",h="Gryphon Master Talonaxe tells of Rhapsody Shindigger, once the finest flyer at the aviary, who took so keenly...",sec={{t="A Fallen Flyer",b="Talonaxe stresses that the dwarves of the aviary all love a good ale, but Rhapsody took to liquor the way a gryphon takes to the skies. No one could fly like Rhapsody, a damned shame as Talonaxe sees it. The first sign of trouble came when Rhapsody stumbled back from the trip with Brohann, and things went downhill fast. In the end Rhapsody had to be let go. The last word is that a brew camp now stands to the east of Aerie Peak.",sp=0}},faq={{q="Who sends you to find Rhapsody Shindigger?",a="Gryphon Master Talonaxe at the Aerie Peak Aviary points you to Rhapsody.",al={"who starts rhapsody shindigger","who gives rhapsody quest","where to start rhapsody"}},{q="Why was Rhapsody Shindigger let go from the aviary?",a="Rhapsody took to liquor the way a gryphon takes to the skies. The first sign of trouble came with a stumbling return from a flight with Brohann, things went downhill quickly, and Talonaxe had to let Rhapsody go.",al={"why was rhapsody fired","what happened to rhapsody","rhapsody shindigger backstory"}},{q="Where is Rhapsody now?",a="Talonaxe has heard that Rhapsody now keeps a brew camp east of the aviary, in the Hinterlands.",al={"where is rhapsody shindigger","rhapsody camp location","how to find rhapsody"}}},kw={"aerie peak","aviary","brohann","gryphon master talonaxe","hinterlands","rhapsody shindigger"},rel={"quest:1450","quest:1452","zone:hinterlands"},m={start="Gryphon Master Talonaxe",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1451},src={"Wowpedia: Rhapsody Shindigger (quest)"}}
E["quest:1452"] = {t="quest",n="Rhapsody's Kalimdor Kocktail",z="hinterlands",s="Rhapsody Shindigger, found in the Hinterlands, will talk about what happened down in the swamp only if given something stiff to drink. A Kalimdor Kocktail needs Roc gizzards from Tanaris and Groddoc and Ironfur livers from Feralas.",h="Rhapsody Shindigger, found in the Hinterlands, will talk about what happened down in the swamp only if given...",sec={{t="A Stiff Drink",b="Rhapsody greets Brohann's messenger with a hiccup. The two of them had quite an adventure, and the tale of what happened down in the swamp, which was not a pretty scene, will only come out with something stiff to drink. Rhapsody has a recipe in mind, the Kalimdor Kocktail, and promises to tell everything once it is brewed.",sp=0},{t="Ingredients from Kalimdor",b="The kocktail needs three Roc gizzards from Tanaris, three Groddoc livers from Feralas and three Ironfur livers, also from Feralas. Even Rhapsody's finest malt is not strong enough to face the memory of that fateful flight over the swamp.",sp=0}},faq={{q="What does Rhapsody want for the Kalimdor Kocktail?",a="Three Roc gizzards, three Groddoc livers and three Ironfur livers. Rhapsody wants a stiff drink before talking about what happened in the swamp.",al={"why kocktail","why roc gizzards","why livers"}},{q="Where do the ingredients come from?",a="The Roc gizzards come from Tanaris. The Groddoc and Ironfur livers come from Feralas.",al={"where to find gizzards","cocktail ingredients location","where are groddocs"}},{q="Who sent you to Rhapsody Shindigger?",a="Brohann, whom Rhapsody calls a crazy fool, sent you. Before that Gryphon Master Talonaxe told you where Rhapsody could be found.",al={"who sent me to rhapsody","previous quest","brohan"}}},kw={"brohann","feralas","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard","tanaris"},rel={"quest:1451","quest:1469","zone:hinterlands","zone:feralas","zone:tanaris"},m={start="Rhapsody Shindigger",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1452},src={"Rhapsody's Kalimdor Kocktail"}}
E["quest:1469"] = {t="quest",n="Rhapsody's Tale",z="hinterlands",s="After Rhapsody Shindigger gets his Kalimdor Kocktail, he finally tells his tale of the flight with Brohann Caskbelly. He hands over an Atal'ai Tablet Fragment and asks that it be taken to Brohann in Stormwind.",h="After Rhapsody Shindigger gets his Kalimdor Kocktail, he finally tells his tale of the flight with Brohann...",sec={{t="A Fragment for Brohann",b="With the kocktail in him, Rhapsody Shindigger finally talks. Before the flight he drank a whole keg of stout, and Brohann followed him through the sky. What he kept from it is a troll souvenir, an Atal'ai Tablet Fragment, and he wants it taken to Brohann Caskbelly in Stormwind.",sp=0},{t="Where the Flight Ended",b="Rhapsody saw no temple from the air. Then, a little too tipsy, he fell off his mount and plunged into the water. He was sucked down and found himself among creepy trolls, and swam out fast, carrying off a souvenir. So Brohann's temple is down there after all.",sp=1}},faq={{q="Who receives the Atal'ai Tablet Fragment?",a="Rhapsody asks that it be brought to Brohann Caskbelly in Stormwind.",al={"who do i give the fragment to","brohann location","where does tablet go"}},{q="What does Rhapsody remember of the flight with Brohann?",a="Rhapsody drank a whole keg of stout before the flight, then zipped around the sky with Brohann following behind.",al={"why did rhapsody fly","brohann and rhapsody"}},{q="What came before this step?",a="Rhapsody's Kalimdor Kocktail came first. Rhapsody would not tell the tale until that drink had been made.",al={"previous quest","prereq rhapsody's tale"}}},kw={"atal'ai","brohann","caskbelly","fragment","hinterlands","rhapsody","shindigger","stormwind","tablet"},rel={"quest:1452","quest:1451","topic:stormwind-kingdom","topic:troll","zone:hinterlands"},m={start="Rhapsody Shindigger",["end"]="Brohann Caskbelly",level="43",faction="Alliance",id=1469},src={"Wowpedia: Rhapsody's Tale"}}
E["quest:2742"] = {t="quest",n="Rin'ji is Trapped!",z="hinterlands",s="Rin'ji, a troll, has lost an axe and been captured in Quel'Danil Lodge, and begs for help to escape. Rin'ji knows that others may not like Rin'ji's kind, but promises something in return and mentions a secret hidden at the Overlook Cliffs.",h="Rin'ji, a troll, has lost an axe and been captured in Quel'Danil Lodge, and begs for help to escape.",sec={{t="A Plea for Escape",b="Rin'ji is a captive at Quel'Danil Lodge and badly frightened. The axe is gone, and Rin'ji begs any passer-by to help get away. Rin'ji knows many dislike Rin'ji's kind, but offers something for a kind soul who helps, and says a secret lies hidden at the Overlook Cliffs.",sp=0},{t="At the End of the Escape",b="What awaits is a troll tablet covered with strange markings. Nothing about the writing can be made out.",sp=1}},faq={{q="Who is Rin'ji?",a="Rin'ji is a troll who lost an axe and was captured at Quel'Danil Lodge in the Hinterlands. Rin'ji speaks of the self in the third person and begs for help to escape.",al={"rinji","who is the troll in quel'danil","who is rin'ji"}},{q="Where is Rin'ji held captive?",a="Rin'ji is held at Quel'Danil Lodge in the Hinterlands.",al={"where is rin'ji","rinji location","quel'danil cage"}},{q="What does Rin'ji offer for help?",a="Rin'ji has something for those who help, and says a secret is hidden at the Overlook Cliffs.",al={"what is rin'ji's secret","rinji reward","what is at overlook cliffs"}}},kw={"captive","escort","hinterlands","overlook cliffs","quel'danil","rin'ji","tablet"},rel={"quest:2782","zone:hinterlands","topic:troll"},m={start="Rin'ji",["end"]="Rin'ji's Secret",level="47",faction="Horde",id=2742},src={"Wowpedia: Rin'ji is Trapped!"}}
E["quest:2782"] = {t="quest",n="Rin'ji's Secret",z="hinterlands",s="After helping Rin'ji, you carry a tablet etched with Witherbark troll markings that nobody has yet read. Oran Snakewrithe, who studies the Witherbark, might decipher it, and lives in the Magic Quarter of the Undercity.",h="After helping Rin'ji, you carry a tablet etched with Witherbark troll markings that nobody has yet read.",sec={{t="A Tablet Nobody Can Read",b="Witherbark troll markings cover the tablet, and what Rin'ji's secret really is remains a mystery. It might be worth a great deal, or it might be worth nothing, because a Witherbark troll in trouble would probably do anything to get out of it.",sp=0},{t="A Scholar in the Undercity",b="Oran Snakewrithe is a well-known scholar of the Witherbark trolls, known to live in the Magic Quarter of the Undercity. Oran might be able to read the tablet.",sp=0}},faq={{q="Where did this tablet come from?",a="It is the secret Rin'ji hid at the Overlook Cliffs, found after helping Rin'ji escape from Quel'Danil Lodge.",al={"rinji tablet source","how do i get the tablet"}},{q="Who can read the markings on the tablet?",a="Oran Snakewrithe, a scholar who knows the Witherbark trolls well, may be able to decipher it.",al={"who can decipher the tablet","who reads witherbark markings"}},{q="Where is Oran Snakewrithe located?",a="Oran is known to live in the Magic Quarter of the Undercity.",al={"oran snakewrithe location","where is oran"}},{q="Is the tablet valuable?",a="Nobody can say. It may be worth a lot or nothing, since a Witherbark troll in distress might try anything to escape trouble.",al={"what is rinji's secret","tablet meaning"}}},kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","tablet","undercity","witherbark"},rel={"quest:2742","zone:undercity","subzone:magic-quarter","zone:hinterlands","topic:troll"},m={start="Rin'ji's Secret",["end"]="Oran Snakewrithe",level="47",faction="Horde",id=2782},src={"Rin'ji's Secret (quest)"}}
E["quest:2877"] = {t="quest",n="Skulk Rock Clean-up",z="hinterlands",s="Fraggar Thundermantle of Aerie Peak wants a clean-up crew for the area around Skulk Rock, which the Horde abandoned and which is now overrun with sludges and oozes. The Wildhammers have plans for the area once it is clear.",h="Fraggar Thundermantle of Aerie Peak wants a clean-up crew for the area around Skulk Rock, which the Horde...",sec={{t="A Matter of Territory",b="The Wildhammers remember the past, more than their brothers in Ironforge do, and Fraggar Thundermantle says friends are made here by getting your hands dirty. The Horde abandoned their positions around Skulk Rock in the Hinterlands, and nasty sludges and oozes have since overrun them. The Wildhammers have plans for that ground, but first it needs a hole made in the infestation.",sp=0},{t="Clearing the Ground",b="Ten green sludges are to be slain, along with ten jade oozes, and then Fraggar waits at Aerie Peak for the report.",sp=0}},faq={{q="Who is Fraggar Thundermantle?",a="Fraggar Thundermantle is a Wildhammer at Aerie Peak in the Hinterlands who wants Skulk Rock cleaned out.",al={"who gives skulk rock clean up","fraggar thundermantle"}},{q="Why do the Wildhammers want Skulk Rock cleared?",a="The Horde abandoned their positions around Skulk Rock and sludges and oozes have taken them over. The Wildhammers have plans for the area but need a clean-up crew first.",al={"why kill the oozes","wildhammer plans skulk rock"}},{q="What creatures dwell at Skulk Rock?",a="Green sludges and jade oozes have overrun the old Horde positions there.",al={"skulk rock mobs","what is at skulk rock"}},{q="Why does Fraggar bring up Ironforge?",a="Fraggar says the Wildhammers remember the past more than their brothers in Ironforge, and that friends are made here by getting your hands dirty.",al={"wildhammer ironforge difference","fraggar ironforge"}}},kw={"aerie peak","fraggar thundermantle","green sludge","hinterlands","jade ooze","skulk rock","wildhammer"},rel={"zone:hinterlands","topic:horde"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="48",faction="Alliance",id=2877},src={"Wowpedia: Skulk Rock Clean-up"}}
E["quest:2880"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="Fraggar Thundermantle of Aerie Peak insists the Wildhammers answer to no Alliance and judge folk by what they do. Five tribal necklaces taken from Hinterlands trolls would be a good start for you.",h="Fraggar Thundermantle of Aerie Peak insists the Wildhammers answer to no Alliance and judge folk by what they...",sec={{t="Earning Wildhammer Regard",b="Fraggar Thundermantle has no use for talk and wants it clear that the Wildhammers are independent. Whoever hopes for friends among them must first prove their worth. Trolls that roam the hillsides of the Hinterlands sometimes wear tribal necklaces, and five of those brought to Fraggar in Aerie Peak would mark a good beginning.",sp=0}},faq={{q="Why does Fraggar Thundermantle want troll necklaces?",a="Fraggar judges people by deeds, not talk, and says five necklaces would mark a good beginning for anyone seeking Wildhammer friendship.",al={"why troll necklaces","troll necklace bounty purpose","why does fraggar want necklaces"}},{q="Are the Wildhammers part of the Alliance?",a="Fraggar is firm that they are not. The Wildhammers are independent and judge people by deeds and actions.",al={"are wildhammers alliance","is aerie peak alliance","wildhammer allegiance"}},{q="Where can troll tribal necklaces be found?",a="Trolls roaming the Hinterlands hillsides are said to carry them now and then.",al={"where to get troll tribal necklace","troll necklace location","how to get troll necklaces"}},{q="Who do I return the necklaces to?",a="Five necklaces go to Fraggar Thundermantle in Aerie Peak.",al={"who gets troll necklaces","fraggar thundermantle turn in","where is fraggar thundermantle"}}},kw={"aerie peak","bounty","fraggar thundermantle","hinterlands","troll tribal necklace","trolls","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",faction="Alliance",id=2880},src={"Wowpedia: Troll Necklace Bounty"}}
E["quest:2881"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="Fraggar Thundermantle, a Wildhammer, has already taken troll tribal necklaces from you once under this bounty. The offer stands for more, as long as you bring them five at a time.",h="Fraggar Thundermantle, a Wildhammer, has already taken troll tribal necklaces from you once under this bounty.",sec={{t="A Standing Offer",b="Fraggar reminds you the first handing-over is behind you, yet more troll tribal necklaces are still welcome whenever you find them and choose to hand them over. Fraggar says those who fight for the Wildhammers will find the Wildhammers ready to fight for them in return. Fraggar counts a batch only when it holds five necklaces.",sp=0},{t="Fraggar's Approval",b="On delivery, Fraggar is plainly pleased, taking the necklaces as proof that you will get your hands dirty. Fraggar says that willingness is prized among the Wildhammers.",sp=1}},faq={{q="Who wants the troll tribal necklaces?",a="Fraggar Thundermantle, who speaks as one of the Wildhammers.",al={"who gives this bounty","fraggar thundermantle role","who takes the necklaces"}},{q="How many troll tribal necklaces are needed?",a="Five at a time. Fraggar says five are needed for them to count.",al={"necklace count","how many necklaces","bounty requirement"}},{q="Why does Fraggar Thundermantle collect these necklaces?",a="Fraggar treats them as a sign of willingness to fight for the Wildhammers, and says those who do will find the Wildhammers willing to fight for them.",al={"why troll necklaces","wildhammer motive","purpose of bounty"}},{q="What came before this bounty?",a="The first Troll Necklace Bounty, which you already completed for Fraggar Thundermantle.",al={"prerequisite quest","previous step","prior bounty"}}},kw={"fraggar thundermantle","hinterlands","tribal necklace","troll necklace bounty","trolls","wildhammer"},rel={"quest:2880","zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",id=2881},src={"Classic quest text: Troll Necklace Bounty"}}
E["quest:2932"] = {t="quest",n="Grim Message",z="hinterlands",s="Nimboya wants the Witherbark trolls punished for betraying Thrall, though they were once allies of the Horde. Nimboya's pike is to carry Witherbark skulls and be planted in a Witherbark village in the Hinterlands.",h="Nimboya wants the Witherbark trolls punished for betraying Thrall, though they were once allies of the Horde.",sec={{t="A Warning in Blood",b="Once the Witherbark trolls stood with the Horde, until they betrayed Thrall. Nimboya hands you a pike and sends you a long way north to the Hinterlands, northeast of Tarren Mill, the village held by the Forsaken. Hunt Witherbark trolls there and collect their skulls, then plant the pike in the ground in Hiri'watha or Zun'watha, two of their smaller villages, so they learn what their deeds cost. Afterwards Nimboya waits in Stranglethorn.",sp=0}},faq={{q="Why does Nimboya want to punish the Witherbark trolls?",a="Nimboya says they were allies of the Horde who turned on Thrall, and that such a betrayal cannot go unpunished.",al={"why attack witherbark","witherbark betrayal","grim message reason"}},{q="Where does Nimboya send you to plant the pike?",a="Either Hiri'watha or Zun'watha, lesser Witherbark villages in the Hinterlands.",al={"where to plant pike","nimboya pike location","grim message location"}},{q="Where are the Hinterlands from Tarren Mill?",a="They lie northeast of Tarren Mill, the village the Forsaken hold, and far to the north of Nimboya in Stranglethorn.",al={"hinterlands location","where is hinterlands"}},{q="Who gives Grim Message?",a="Nimboya, in Stranglethorn, hands over the pike and waits there for word.",al={"grim message questgiver","who is nimboya"}}},kw={"grim message","hinterlands","hiri'watha","nimboya","tarren mill","thrall","witherbark","zun'watha"},rel={"npc:thrall","zone:hinterlands","topic:horde","topic:troll","subzone:tarren-mill","topic:forsaken"},m={start="Nimboya",["end"]="Nimboya",level="42",faction="Horde",id=2932},src={"Wowpedia: Grim Message"}}
E["quest:2933"] = {t="quest",n="Venom Bottles",z="hinterlands",s="Bottles of a vile green venom fill a Witherbark village in the Hinterlands. So many of them suggest the Witherbarks value it highly, and an apothecary in nearby Tarren Mill might like a sample.",h="Bottles of a vile green venom fill a Witherbark village in the Hinterlands.",sec={{t="A Toxic Discovery",b="The bottles in the Witherbark village hold a vile, green venom. There are so many that the Witherbarks must consider it very important. A sample could be carried to an apothecary in Tarren Mill, who may want to see it.",sp=0},{t="Lydon's Verdict",b="Apothecary Lydon, whose experiments have all failed that day, takes the bottle and declares the contents venom drawn from some arachnoid creature. Lydon asks where it came from.",sp=1}},faq={{q="Where are the venom bottles found?",a="They are in a Witherbark village in the Hinterlands, in great numbers.",al={"venom bottle location","where to find venom bottles","witherbark venom"}},{q="Who is interested in the venom bottles?",a="The suggestion is to take a sample to an apothecary in Tarren Mill, and Apothecary Lydon is the one to see.",al={"who wants the venom","where to turn in venom bottle","tarren mill apothecary"}},{q="What is in the bottles?",a="A vile, green venom, and the Witherbarks seem to value it highly given how many bottles they keep.",al={"what is the venom","what is in the bottles"}}},kw={"apothecary lydon","arachnoid","hinterlands","tarren mill","troll venom","venom bottle","witherbark"},rel={"zone:hinterlands","subzone:tarren-mill","quest:2934"},m={start="Venom Bottle",["end"]="Apothecary Lydon",level="43",faction="Horde",id=2933},src={"Venom Bottles"}}
E["quest:2934"] = {t="quest",n="Undamaged Venom Sac",z="hinterlands",s="Apothecary Lydon in Tarren Mill wants a fresh sample of the venom already delivered, and sends you after the spiders that yield it in the Hinterlands. Time matters, since it must arrive fresh.",h="Apothecary Lydon in Tarren Mill wants a fresh sample of the venom already delivered, and sends you after the...",sec={{t="A Fresh Sample",b="After Venom Bottles, Apothecary Lydon asks for something fresher. The spiders that yielded the venom must live in the Hinterlands, and an undamaged venom sac is wanted from them. Many roam near the troll city of Shadra'Alor. There is no time to waste, because the sac has to be fresh on arrival. Lydon is eager to run experiments with it, and has ordered in several small, terribly cute animals to test it on.",sp=0}},faq={{q="Who requests the undamaged venom sac?",a="Apothecary Lydon in Tarren Mill asks for it and waits there for it.",al={"who gives undamaged venom sac","who starts undamaged venom sac","undamaged venom sac quest giver"}},{q="Where can the spiders be found?",a="In the Hinterlands, where many spiders are found near the troll city of Shadra'Alor.",al={"spider location","where are the spiders","where to find undamaged venom sac"}},{q="Why does Apothecary Lydon say not to tarry?",a="Freshness is essential, so Lydon wants the sac delivered without delay.",al={"why is it timed","why does the sac spoil","undamaged venom sac timer"}},{q="What came before this step?",a="It follows Venom Bottles, in which a sample of venom from a Witherbark village was brought to Lydon.",al={"previous quest","what quest comes before undamaged venom sac","undamaged venom sac prerequisite"}}},kw={"apothecary lydon","hinterlands","shadra'alor","spider venom","tarren mill","venom sac"},rel={"quest:2933","quest:2935","subzone:tarren-mill","zone:hinterlands"},m={start="Apothecary Lydon",["end"]="Apothecary Lydon",level="45",faction="Horde",id=2934},src={"Undamaged Venom Sac (quest)"}}
E["quest:2935"] = {t="quest",n="Consult Master Gadrin",z="hinterlands",s="Apothecary Lydon found the venom from the broodguards less potent than the sample you first brought, which points to another kind of spider. Lydon sends you to Master Gadrin in Sen'jin Village, in Durotar, who may know more.",h="Apothecary Lydon found the venom from the broodguards less potent than the sample you first brought, which...",sec={{t="A Search for Potency",b="Apothecary Lydon found the venom taken from the broodguards weaker than the sample you brought first, so it must come from a different spider. Lydon wants a fresh sample of the stronger kind. To learn where it comes from, ask a troll well acquainted with the Witherbark: Master Gadrin, in Sen'jin Village, in Durotar. With luck, Gadrin can name the source of that venom.",sp=0}},faq={{q="Why does Apothecary Lydon send you to Master Gadrin?",a="The broodguard venom was weaker than the first sample, which points to a different spider. Gadrin is a troll well acquainted with the Witherbark and may be able to name the source of that venom.",al={"why consult gadrin","why go to senjin","lydon gadrin"}},{q="Where is Master Gadrin located?",a="Master Gadrin is in Sen'jin Village, in Durotar.",al={"where is gadrin","master gadrin location","find master gadrin"}},{q="What came before this journey?",a="Before this you brought Apothecary Lydon an undamaged venom sac from the Hinterlands.",al={"prereq","what was before this","previous quest"}}},kw={"apothecary lydon","consult master gadrin","durotar","hinterlands","master gadrin","sen'jin village","venom","witherbark"},rel={"npc:master-gadrin","subzone:sen-jin-village","zone:durotar","zone:hinterlands","topic:troll"},m={start="Apothecary Lydon",["end"]="Master Gadrin",level="45",faction="Horde",id=2935},src={"Consult Master Gadrin"}}
E["quest:2937"] = {t="quest",n="Summoning Shadra",z="hinterlands",s="Master Gadrin gives you a parchment to read at the altar of Shadra'Alor, deep in the Witherbark realm of the Hinterlands, to summon Shadra the spider god. Her venom is then to be carried to Apothecary Lydon in Tarren Mill.",h="Master Gadrin gives you a parchment to read at the altar of Shadra'Alor, deep in the Witherbark realm of the...",sec={{t="Call of the Spider God",b="Gadrin's parchment is meant to be read at Shadra'Alor's altar, deep within the Witherbark realm of the Hinterlands. Doing so calls up Shadra the spider god. She must be defeated there, and her venom taken to Apothecary Lydon in Tarren Mill.",sp=0}},faq={{q="Who provides the parchment to summon Shadra?",a="Master Gadrin gives you the parchment.",al={"who gives summoning shadra","summoning shadra questgiver"}},{q="Where is Shadra summoned?",a="In the Hinterlands, at Shadra'Alor's altar, well inside the Witherbark realm.",al={"where to summon shadra","altar of shadra'alor location","shadra location"}},{q="Who receives the venom once Shadra is defeated?",a="Apothecary Lydon, in Tarren Mill.",al={"who do i turn the venom into","summoning shadra turn in","apothecary lydon location"}}},kw={"apothecary lydon","hinterlands","master gadrin","shadra","shadra'alor","spider god","tarren mill","witherbark"},rel={"quest:2938","npc:master-gadrin","zone:hinterlands","subzone:tarren-mill"},m={start="Master Gadrin",["end"]="Apothecary Lydon",level="55",faction="Horde",id=2937},src={"Summoning Shadra (Classic)"}}
E["quest:2938"] = {t="quest",n="Venom to the Undercity",z="hinterlands",s="Apothecary Lydon is delighted with the venom taken from the Witherbark's spider god, and wants a sample sent to Lydon's superior, Faranell, at the Apothecarium in the Undercity. A parcel is entrusted to you for the journey.",h="Apothecary Lydon is delighted with the venom taken from the Witherbark's spider god, and wants a sample sent...",sec={{t="A Potent Find",b="Lydon has killed nearly two dozen rabbits with a single dose of the venom. Some of them were tiny, so their resistance was surely low, but there is no denying the poison is powerful. Lydon is certain that Faranell will want to test it personally, and hands you a parcel to carry to the Apothecarium in the Undercity.",sp=0}},faq={{q="Who is sending the parcel to the Undercity?",a="Apothecary Lydon sends it, after testing the venom taken from the Witherbark's spider god.",al={"who gives venom to the undercity","quest giver venom to the undercity","who starts venom to the undercity"}},{q="Who is supposed to receive the venom in the Undercity?",a="Master Apothecary Faranell, Lydon's superior, in the Apothecarium of the Undercity.",al={"who gets the parcel","where does venom go undercity","who is faranell"}},{q="How potent was the venom during testing?",a="A single dose was enough to kill nearly two dozen rabbits, though some were very young and tiny.",al={"how strong is shadra venom","lydon rabbit tests"}},{q="What comes before this delivery?",a="It follows Summoning Shadra, in which the venom was taken from the spider god.",al={"previous quest venom to the undercity","prerequisite venom to the undercity"}}},kw={"apothecarium","apothecary lydon","faranell's parcel","master apothecary faranell","shadra","venom to the undercity"},rel={"npc:master-apothecary-faranell","subzone:apothecarium","zone:undercity","zone:hinterlands"},m={start="Apothecary Lydon",["end"]="Master Apothecary Faranell",level="55",faction="Horde",id=2938},src={"Venom to the Undercity"}}
E["quest:2988"] = {t="quest",n="Witherbark Cages",z="hinterlands",s="Gryphon Master Talonaxe tells you that Sharpbeak, heir of Swiftwing, the mightiest gryphon, has been lost, and that trolls are believed to have taken the young gryphon. You are asked to look through the cages of the two Witherbark troll villages for any sign of Sharpbeak.",h="Gryphon Master Talonaxe tells you that Sharpbeak, heir of Swiftwing, the mightiest gryphon, has been lost...",sec={{t="A Missing Heir",b="Sharpbeak was lost a few days ago while hunting with his parents. Talonaxe and the others believe the trolls took him, and you are asked for your help. Three cages wait to be checked across the two Witherbark troll villages, and Talonaxe wants to hear what you find.",sp=0},{t="Word From the Villages",b="Sharpbeak is not in the Witherbark villages. Talonaxe takes the news gravely. The young gryphon is meant to lead the generation that follows, and if he is lost, the strength and spirit of the fleet will suffer greatly.",sp=1}},faq={{q="Who is Sharpbeak?",a="Sharpbeak is the heir of Swiftwing, whom Talonaxe calls the mightiest gryphon. He was lost a few days ago while hunting with his parents.",al={"sharpbeak","who is the gryphon","swiftwing heir"}},{q="Why are the Witherbark trolls suspected?",a="Talonaxe and the others believe the trolls took Sharpbeak, so the cages of the Witherbark villages are the first place to look.",al={"why trolls","witherbark involvement","who took sharpbeak"}},{q="Where do I search for Sharpbeak?",a="Look in the cages of the two Witherbark troll villages, then come back and tell Gryphon Master Talonaxe what you found.",al={"where are the cages","witherbark cages location","where to look for sharpbeak"}}},kw={"cages","gryphon","hinterlands","sharpbeak","swiftwing","talonaxe","trolls","witherbark"},rel={"quest:2989","quest:1450","zone:hinterlands","topic:troll","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="45",faction="Alliance",id=2988},src={"Wowpedia: Witherbark Cages"}}
E["quest:2989"] = {t="quest",n="The Altar of Zul",z="hinterlands",s="The Witherbark trolls do not have Sharpbeak, so Gryphon Master Talonaxe wonders whether the Vilebranch trolls took the young gryphon instead. You are sent to the Altar of Zul, at the western edge of Vilebranch lands, to search for him.",h="The Witherbark trolls do not have Sharpbeak, so Gryphon Master Talonaxe wonders whether the Vilebranch trolls...",sec={{t="Another Tribe, Another Search",b="The cages of the Witherbark trolls held no sign of Sharpbeak. Talonaxe now suspects the Vilebranch trolls and sends you up to the Altar of Zul, at the western edge of their lands, to look on its top for the gryphon child. Talonaxe fears to think what the Vilebranch may be doing to the captive, if they hold him.",sp=0},{t="Word From the Altar",b="Sharpbeak is not at the altar. Talonaxe calls it bad news and good news at once: the Vilebranch trolls are known to carry out sacrifices, so it is a relief that the gryphon was not found there. Talonaxe thanks you for your aid and says a greater undertaking lies ahead.",sp=1}},faq={{q="Why does Gryphon Master Talonaxe send you to the Altar of Zul?",a="The Witherbark trolls do not have Sharpbeak, so Talonaxe thinks the Vilebranch trolls may have taken him.",al={"why altar of zul","altar of zul reason","why go to altar of zul"}},{q="Where is the Altar of Zul located?",a="The Altar of Zul lies at the western edge of Vilebranch lands in the Hinterlands. You are to check the top of it.",al={"altar of zul location","where is altar of zul"}},{q="Who is Sharpbeak?",a="Sharpbeak is Swiftwing's heir, the gryphon child Talonaxe has been searching for since he went missing.",al={"who is sharpbeak","sharpbeak lore"}},{q="Why is Talonaxe worried about the Vilebranch trolls?",a="Talonaxe fears that if the Vilebranch have Sharpbeak, no one can know what they are doing with him.",al={"why are vilebranch dangerous","what do vilebranch do"}}},kw={"altar of zul","gryphon master talonaxe","hinterlands","sharpbeak","vilebranch","witherbark"},rel={"quest:1450","quest:2988","zone:hinterlands","topic:troll","quest:2992","quest:2993","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="48",faction="Alliance",id=2989},src={"Wowpedia: The Altar of Zul (quest)"}}
E["quest:2990"] = {t="quest",n="Thadius Grimshade",z="hinterlands",s="Gryphon Master Talonaxe hands you a feather taken from the gryphon child Sharpbeak's nest. You are to carry it to the diviner Thadius Grimshade, who dwells in Nethergarde Keep's mage tower in the Blasted Lands.",h="Gryphon Master Talonaxe hands you a feather taken from the gryphon child Sharpbeak's nest.",sec={{t="A Plea to a Diviner",b="Years ago Thadius Grimshade quit Aerie Peak to chase darker knowledge, yet Talonaxe says he remains a Wildhammer at heart. With luck, divining magic and the feather from Sharpbeak's nest will let Thadius find the gryphon child. Talonaxe says Thadius is to be found in the mage tower at Nethergarde Keep, in the Blasted Lands.",sp=0},{t="The Diviner's Welcome",b="Thadius greets you as someone bearing a gift. He knows the feather at once as belonging to a fine gryphon, one meant for great things if he lives to grow up unharmed. He then tells you to listen closely.",sp=1}},faq={{q="Who is Thadius Grimshade?",a="Thadius Grimshade is a diviner. He quit Aerie Peak years ago to chase darker knowledge, though Talonaxe says he remains a Wildhammer at heart.",al={"thadius grimshade lore","who is thadius"}},{q="Why do you need Sharpbeak's feather?",a="The feather was gathered at the nest where Sharpbeak sleeps. Talonaxe hopes Thadius can use his divining magics on it to find the young gryphon.",al={"why sharpbeak feather","feather purpose"}},{q="Where is Thadius Grimshade located?",a="Thadius Grimshade dwells in the Blasted Lands, in Nethergarde Keep's mage tower.",al={"thadius grimshade location","where is thadius"}}},kw={"aerie peak","blasted lands","divination","gryphon","nethergarde keep","sharpbeak","talonaxe","thadius grimshade"},rel={"npc:thadius-grimshade","quest:1450","subzone:nethergarde-keep","zone:blastedlands","zone:hinterlands","quest:2989","quest:2992","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Thadius Grimshade",level="47",faction="Alliance",id=2990},src={"Thadius Grimshade (quest)"}}
E["quest:2992"] = {t="quest",n="The Divination",z="hinterlands",s="Thadius Grimshade asks you to give him room while he performs a ritual of divination. He means to follow the link between the feather you brought and its owner until it leads him to Sharpbeak.",h="Thadius Grimshade asks you to give him room while he performs a ritual of divination.",sec={{t="A Ritual of Divination",b="Thadius follows the link between Sharpbeak's feather and the gryphon who owns it, hoping to reach Sharpbeak himself. He asks for silence and room to work. He admits it may not go to plan, and warns that in that case you had better close your eyes.",sp=0},{t="When the Ritual Ends",b="The ritual succeeds. Thadius has glimpsed Sharpbeak and is able to tell you where to look.",sp=1}},faq={{q="What is Thadius Grimshade doing in this ritual?",a="Thadius performs a ritual of divination. He seeks the link between the feather you brought and Sharpbeak, and means to follow it to Sharpbeak himself.",al={"what is the divination","grimshade ritual","how does grimshade find sharpbeak"}},{q="Who is Sharpbeak?",a="Sharpbeak is the gryphon child whose feather you brought to Thadius, and whom Gryphon Master Talonaxe has been trying to find.",al={"sharpbeak","who is sharpbeak"}},{q="Is the ritual dangerous?",a="Thadius warns that if the ritual does not go according to plan, you had better close your eyes. He asks you to give him room while he works.",al={"is the divination dangerous","why close my eyes","divination risk"}}},kw={"feather","gryphon","ritual","sharpbeak","thadius grimshade","the divination"},rel={"npc:thadius-grimshade","quest:2993","quest:2994","quest:2989","quest:2988","zone:blastedlands"},m={start="Thadius Grimshade",["end"]="Thadius Grimshade",level="47",faction="Alliance",id=2992},src={"The Divination"}}
E["quest:2993"] = {t="quest",n="Return to the Hinterlands",z="hinterlands",s="Thadius Grimshade tells you where Sharpbeak is kept: in a cage on a high cliff, atop Jintha'Alor in the Hinterlands. Vile Priestess Hexx, high priestess of the Vilebranch trolls, has the key. You are to carry the news to Gryphon Master Talonaxe.",h="Thadius Grimshade tells you where Sharpbeak is kept: in a cage on a high cliff, atop Jintha'Alor in the...",sec={{t="Where Sharpbeak Is Held",b="Having done his part, Thadius wishes you fortune and tells you what he learned. Sharpbeak sits caged on a high cliff, atop Jintha'Alor in the Hinterlands. Vile Priestess Hexx, high priestess of the Vilebranch trolls, possesses the key to that cage. Take word of this to Gryphon Master Talonaxe.",sp=0},{t="Talonaxe's Answer",b="Talonaxe asks what Thadius said. Told that the Vilebranch trolls have Sharpbeak, Talonaxe finds it unbearable and declares that a force must be organized to get the gryphon back.",sp=1}},faq={{q="Who reveals the location of Sharpbeak?",a="Thadius Grimshade, who performed the ritual of divination and then told you where Sharpbeak is held.",al={"who tells you where sharpbeak is","sharpbeak location source","who finds sharpbeak"}},{q="Where is Sharpbeak being held?",a="Sharpbeak is caged on a high cliff, atop Jintha'Alor in the Hinterlands.",al={"where is sharpbeak","sharpbeak cage location","sharpbeak cliff"}},{q="Who holds the key to Sharpbeak's cage?",a="Vile Priestess Hexx, high priestess of the Vilebranch trolls, holds the key.",al={"sharpbeak key","who has cage key","vile priestess hexx key"}},{q="Where do you deliver this news?",a="Take it to Gryphon Master Talonaxe in the Hinterlands.",al={"who do i return to","where to turn in return to the hinterlands","gryphon master talonaxe location"}},{q="What came before this journey?",a="Thadius Grimshade had just performed the ritual of divination to find Sharpbeak.",al={"previous quest","what led to return to the hinterlands","preceding step"}}},kw={"gryphon master talonaxe","hinterlands","jintha'alor","sharpbeak","thadius grimshade","vile priestess hexx","vilebranch"},rel={"quest:2992","quest:2994","npc:thadius-grimshade","quest:1450","zone:hinterlands","topic:troll","quest:2989","quest:2988"},m={start="Thadius Grimshade",["end"]="Gryphon Master Talonaxe",level="47",faction="Alliance",id=2993},src={"Return to the Hinterlands"}}
E["quest:2994"] = {t="quest",n="Saving Sharpbeak",z="hinterlands",s="Gryphon Master Talonaxe sends you to the summit of Jintha'Alor, which stands in the heart of Vilebranch territory. Vile Priestess Hexx has the key to Sharpbeak's cage, and you are to take it from her and free the gryphon.",h="Gryphon Master Talonaxe sends you to the summit of Jintha'Alor, which stands in the heart of Vilebranch...",sec={{t="Up Jintha'Alor",b="Following Thadius Grimshade's divination and your report to Talonaxe, the way to rescue Sharpbeak is clear. Jintha'Alor stands in the heart of Vilebranch territory, and you are to fight your way to its summit. Vile Priestess Hexx holds the key to Sharpbeak's cage. Take it from her, then find the cage and save the gryphon.",sp=0},{t="Talonaxe's Thanks",b="Swiftwind and Keenclaw have already brought their child home and cannot stop fussing over him. The sight leaves Talonaxe misty-eyed. Talonaxe says the debt cannot be repaid, and that Aerie Peak's gryphons and riders will long sing your name.",sp=1}},faq={{q="Who sends you to rescue Sharpbeak?",a="Gryphon Master Talonaxe asks you to rescue Sharpbeak, after the divination revealed where the gryphon is held.",al={"who gives saving sharpbeak","sharpbeak questgiver","where do i start saving sharpbeak"}},{q="Where is Sharpbeak being held?",a="Sharpbeak is caged at the summit of Jintha'Alor, a place within Vilebranch territory in the Hinterlands.",al={"where is sharpbeak","sharpbeak location","where is sharpbeak cage"}},{q="Who holds the key to Sharpbeak's cage?",a="Vile Priestess Hexx has the key needed to open Sharpbeak's cage.",al={"who drops sharpbeak key","where is hexx key","vile priestess hexx key"}}},kw={"aerie peak","gryphon master talonaxe","hinterlands","jintha'alor","saving sharpbeak","sharpbeak","vile priestess hexx","vilebranch"},rel={"quest:2993","quest:2992","zone:hinterlands","npc:thadius-grimshade","quest:2989","quest:2988"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="51",faction="Alliance",id=2994},src={"Wowpedia: Saving Sharpbeak"}}
E["quest:4787"] = {t="quest",n="The Ancient Egg",z="hinterlands",s="Yeh'kinya in Tanaris tells of an ancient egg named in the Prophecy of Mosh'aru, left from the age when trolls held vast empires. It can contain Hakkar's essence, and Yeh'kinya wants it fetched from Jintha'Alor in the Hinterlands.",h="Yeh'kinya in Tanaris tells of an ancient egg named in the Prophecy of Mosh'aru, left from the age when trolls...",sec={{t="A Relic of Troll Empires",b="An ancient egg is spoken of in the Prophecy of Mosh'aru, a relic of the age when trolls held vast empires. Its power can contain Hakkar's essence, and Yeh'kinya believes it could be the sole means of guarding the world from his evil.",sp=0},{t="Behind the Amphitheater",b="Yeh'kinya asks you to bring the egg to Tanaris. Tales say it lies concealed far inside Jintha'Alor in the Hinterlands, within a cave behind the amphitheater atop the city. Yeh'kinya senses great forces stirring and fears that time is running short.",sp=0}},faq={{q="What is the ancient egg?",a="It is a relic from the age when trolls held vast empires, spoken of in the Prophecy of Mosh'aru. Its power can contain Hakkar's essence.",al={"ancient egg lore","what does the egg do","prophecy of mosharu egg"}},{q="Why does Yeh'kinya want the egg?",a="Yeh'kinya believes the egg could be the sole means of guarding the world from Hakkar's evil.",al={"why find the egg","yehkinya purpose","stop hakkar egg"}},{q="Where is the egg hidden?",a="Tales place it deep inside Jintha'Alor, in a cave behind the amphitheater that crowns the city.",al={"where is the ancient egg","ancient egg location","egg cave jinthaalor"}},{q="Who wants the egg brought to them?",a="Yeh'kinya, who waits in Tanaris, wants the ancient egg brought there.",al={"who starts ancient egg","who gives the quest","yehkinya questgiver"}}},kw={"ancient egg","hakkar","hinterlands","jintha'alor","mosh'aru","prophecy","tanaris","yeh'kinya"},rel={"npc:yeh-kinya","zone:hinterlands","zone:tanaris","topic:troll"},m={start="Yeh'kinya",["end"]="Yeh'kinya",level="50",faction="Neutral",id=4787},src={"The Ancient Egg"}}
E["quest:485"] = {t="quest",n="Find OOX-09/HL!",z="hinterlands",s="An egg-shaped metal device in the Hinterlands springs open at the turn of a knob, and a gnome named Oglethorpe Obnoticus speaks from inside it. A homing robot of Oglethorpe's has crashed near Skulk Rock, and the beacon is to be carried to it.",h="An egg-shaped metal device in the Hinterlands springs open at the turn of a knob, and a gnome named...",sec={{t="A Crackling Call",b="Fiddle with a knob on the strange metal egg and it opens into a gnomish contraption. A crackling voice gives the name Oglethorpe Obnoticus and says the homing robot has crashed. The coordinates have been worked out: the robot came down where the river begins, close to Skulk Rock. The beacon is to be taken to it.",sp=0},{t="The Wreckage at the River",b="At the river's head lies the wreckage of something that looks like a robotic chicken. The voice from the egg confirms that it is the homing robot. A jump start comes first, since only then can it return to Booty Bay for mending, and the beacon is to be placed inside it.",sp=0}},faq={{q="Who is speaking through the distress beacon?",a="The voice is a gnome calling themselves Oglethorpe Obnoticus, whose homing robot has crashed in the Hinterlands.",al={"who made the beacon","who is oglethorpe","who is speaking"}},{q="Where did the robot crash?",a="Oglethorpe's computed coordinates put it where the river begins, near Skulk Rock in the Hinterlands.",al={"where is the robot","oox 09 hl location","where to find robot"}},{q="What does the homing robot look like?",a="The wreck looks like a robotic chicken.",al={"what is the robot","chicken robot","what does oox look like"}},{q="What is the beacon for?",a="Without a jump start the robot cannot make its way back to Booty Bay for repairs, and the beacon goes inside it to give that.",al={"how to activate robot","what to do with the beacon","how to complete find oox-09/hl"}}},kw={"booty bay","distress beacon","hinterlands","homing robot","oglethorpe obnoticus","oox-09/hl","skulk rock"},rel={"quest:836","subzone:booty-bay","zone:hinterlands"},m={start="OOX-09/HL Distress Beacon",["end"]="Homing Robot OOX-09/HL",level="48",faction="Neutral",id=485},src={"Wowpedia: Find OOX-09/HL!"}}
E["quest:77"] = {t="quest",n="A Sticky Situation",z="hinterlands",s="Gilveradin Sunchaser holds the original packaging for the Hinterlands Honey Ripple that Dran Droffers is after, and will help package it for a fee of two extra bottles. The bottles are in crates around the abandoned Horde base near Skulk Rock.",h="Gilveradin Sunchaser holds the original packaging for the Hinterlands Honey Ripple that Dran Droffers is...",sec={{t="A Matter of Packaging",b="Dran Droffers seeks the ripple, and Gilveradin Sunchaser has the original packaging for it. The help is not free: Gilveradin wants two additional bottles for the trouble. Ten bottles of Hinterlands Honey Ripple are to be gathered and brought back to the camp.",sp=0},{t="Ruins of Skulk Rock",b="The crates stand around the abandoned Horde base near Skulk Rock. Foul slimes and oozes cling to the ruins, and rumor says some sort of master ooze leads them.",sp=0}},faq={{q="Who wants the Hinterlands Honey Ripple packaged?",a="Dran Droffers is the one seeking the ripple, and Gilveradin Sunchaser has the original packaging for it, which is meant for Malton's father.",al={"who needs the ripple","dran droffers ripple","who is the packaging for"}},{q="What does Gilveradin charge for the packaging?",a="Gilveradin asks for two additional bottles of the ripple as a fee. Ten bottles are to be recovered from the crates.",al={"why 10 bottles","gilveradin fee","why so much ripple"}},{q="Where are the crates of Hinterlands Honey Ripple kept?",a="They are in crates around the abandoned Horde base near Skulk Rock in the Hinterlands.",al={"ripple location","where is the honey ripple","skulk rock crates"}},{q="What is at the abandoned camp at Skulk Rock?",a="Foul slimes and oozes cling to the ruins, and rumor says a master ooze leads them.",al={"skulk rock monsters","what is at skulk rock","skulk rock oozes"}}},kw={"dran droffers","gilveradin sunchaser","hinterlands","hinterlands honey ripple","oozes","skulk rock","slimes"},rel={"zone:hinterlands","topic:horde"},m={start="Gilveradin Sunchaser",["end"]="Gilveradin Sunchaser",level="48",faction="Horde",id=77},src={"Wowpedia: A Sticky Situation"}}
E["quest:7815"] = {t="quest",n="Snapjaws, Mon!",z="hinterlands",s="In the Hinterlands, Katoom the Angler of Revantusk Village can barely keep a line in the water because saltwater snapjaws keep wrecking it and stealing his bait. He wants fifteen of the turtles dead.",h="In the Hinterlands, Katoom the Angler of Revantusk Village can barely keep a line in the water because...",sec={{t="Trouble on the Line",b="Katoom urges you not to be taken in by the snapjaws' large eyes and calls the turtles a menace. By his account, he cannot fish for even five minutes before one of them tears his line and makes off with his bait. He asks you, as a favor to himself and to his neighbours in the village, to wipe out the whole lot; the count is fifteen.",sp=0}},faq={{q="Who asks you to hunt the turtles?",a="Katoom the Angler, a fisher of Revantusk in the Hinterlands.",al={"who gives snapjaws mon","snapjaws mon quest giver","katoom the angler"}},{q="Why does Katoom want the saltwater snapjaws killed?",a="Katoom says they break his fishing line and steal his bait, so he cannot fish for even five minutes in peace.",al={"why kill snapjaws","turtle nuisance","why kill turtles revantusk"}},{q="How many snapjaws need to be slain?",a="Fifteen saltwater snapjaw turtles.",al={"how many turtles","snapjaw count","snapjaws mon count"}}},kw={"angler","bait","fishing","hinterlands","katoom","revantusk","snapjaws","turtles"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="50",id=7815},src={"Classic quest text: Snapjaws, Mon!"}}
E["quest:7816"] = {t="quest",n="Gammerita, Mon!",z="hinterlands",s="Katoom the Angler, from Revantusk Village in the Hinterlands, has lost his best lure to Gammerita, the head of the saltwater snapjaws. You are asked to find her and get it back.",h="Katoom the Angler, from Revantusk Village in the Hinterlands, has lost his best lure to Gammerita, the head...",sec={{t="A Thief Among the Turtles",b="Katoom describes Gammerita as no ordinary turtle: she heads the saltwater snapjaws, and Katoom brands her a thief. She snapped his best lure off his line, and since then the fish have not bitten the way they used to.",sp=0},{t="Getting the Lure Back",b="Katoom wants you to find Gammerita and recover the lure from her stomach. Gammerita keeps to the coast, among the other turtles.",sp=0},{t="Katoom's Hopes",b="With the lure back in hand and fewer snapjaws about, Katoom expects the fish to come in by the heap.",sp=1}},faq={{q="Who is Katoom the Angler?",a="A fisher of Revantusk in the Hinterlands, who asks you to hunt Gammerita.",al={"who is katoom","katoom revantusk","katoom location"}},{q="What is Gammerita?",a="A turtle unlike the others, who heads the saltwater snapjaws and whom Katoom calls a thief.",al={"who is gammerita","what is gammerita","gammerita turtle"}},{q="Why does Katoom want Gammerita dead?",a="Gammerita snapped Katoom's best lure off his line, and the fish have not been biting the same since. Katoom wants the lure back from her stomach.",al={"why kill gammerita","what did gammerita steal","katoom motive"}},{q="Where can Gammerita be found?",a="On the coast, where she keeps company with the other saltwater snapjaw turtles.",al={"where is gammerita","gammerita location","find gammerita"}}},kw={"angler","gammerita","hinterlands","katoom","lure","revantusk","snapjaw","turtle"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="48",id=7816},src={"Classic quest text: Gammerita, Mon!"}}
E["quest:7828"] = {t="quest",n="Stalking the Stalkers",z="hinterlands",s="Huntsman Markhor, of the village of Revantusk in the Hinterlands, names the Silvermane wolves as one of the worst dangers to the village's hunters. You are asked to turn the tables and hunt the hunters.",h="Huntsman Markhor, of the village of Revantusk in the Hinterlands, names the Silvermane wolves as one of the...",sec={{t="Wolves in Hiding",b="Markhor points to the many trolls the Hinterlands wilds have already claimed, and ranks the Silvermane wolves among the greatest dangers to Revantusk's hunters. The wolves wait hidden among the bushes and the lay of the land, then pounce when the moment is right. Markhor will not let that go unanswered, and urges you to think as a Silvermane does and turn the hunt on the hunters, putting every one of them down.",sp=0},{t="What Markhor Asks",b="Markhor wants fifteen Silvermane Stalkers and fifteen Silvermane Howlers killed. Markhor adds that the wolves lurk out in the Hinterlands wilds.",sp=0},{t="Revantusk's Thanks",b="Once it is done, Markhor thanks you on behalf of the Revantusk for what you have given them.",sp=1}},faq={{q="Who asks for the wolves to be hunted?",a="Huntsman Markhor, of the village of Revantusk in the Hinterlands.",al={"who gives stalking the stalkers","quest giver stalking the stalkers","markhor quest"}},{q="Why are the Silvermane wolves such a threat?",a="Markhor ranks them among the greatest dangers to Revantusk's hunters: they hide among bushes and the lay of the land and strike when the chance comes, and many trolls have already been lost out in the wilds.",al={"why kill silvermane wolves","silvermane wolf threat","why cull wolves hinterlands"}},{q="Which wolves need to be culled?",a="Fifteen Silvermane Stalkers and fifteen Silvermane Howlers.",al={"what wolves to kill","stalking the stalkers targets","wolf types hinterlands"}},{q="Where are these wolves found?",a="Markhor says they lurk out in the Hinterlands wilds.",al={"where are silvermane wolves","silvermane stalker location","silvermane howler location"}}},kw={"hinterlands wolves","huntsman markhor","revantusk","revantusk village","silvermane howler","silvermane stalker","stalking the stalkers"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",id=7828},src={"Classic quest text: Stalking the Stalkers"}}
E["quest:7829"] = {t="quest",n="Hunt the Savages",z="hinterlands",s="Huntsman Markhor, of the village of Revantusk in the Hinterlands, calls the savage owlbeasts some of the region's most ornery creatures and asks you to kill twenty of them.",h="Huntsman Markhor, of the village of Revantusk in the Hinterlands, calls the savage owlbeasts some of the...",sec={{t="Claws and Beaks",b="Markhor describes the savage owlbeasts as among the more ornery creatures of the Hinterlands, and says the claws and beaks of the beasts have cost Revantusk many good warriors. Markhor wants every one you see killed, until you can bear no more bloodshed, and then the contribution you made will be weighed and judged. Twenty must fall.",sp=0},{t="Clearing the Mind",b="Markhor's counsel for the hunt is to clear the mind of unclean thoughts and join with the wild. The owlbeasts are out in the Hinterlands wilds.",sp=0},{t="Markhor's Judgment",b="After the hunt, Markhor names you a worthy friend to the Revantusk.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor, of the village of Revantusk in the Hinterlands.",al={"who gives hunt the savages","hunt the savages quest giver","huntsman markhor quest"}},{q="Why does Markhor want the savage owlbeasts killed?",a="Markhor calls them ornery and says they have claimed many good Revantusk warriors with their claws and beaks.",al={"why kill savage owlbeasts","reason for hunting owlbeasts","why hunt the savages"}},{q="Where can the savage owlbeasts be found?",a="Markhor says they dwell in the Hinterlands wilds.",al={"savage owlbeast location","where are savage owlbeasts","owlbeasts in hinterlands"}},{q="How many savage owlbeasts must be slain?",a="Twenty savage owlbeasts.",al={"how many owlbeasts to kill","hunt the savages requirement"}}},kw={"hinterlands","hunt the savages","huntsman markhor","owlbeasts","revantusk","revantusk village","savage owlbeast"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",id=7829},src={"Classic quest text: Hunt the Savages"}}
E["quest:7830"] = {t="quest",n="Avenging the Fallen",z="hinterlands",s="Huntsman Markhor of Revantusk Village says the Wildhammer train gryphons to slay trolls, and he wants the elder gryphons of the region, the Skylords, wiped out. You are to slay a Razorbeak Skylord and bring its plume back to him.",h="Huntsman Markhor of Revantusk Village says the Wildhammer train gryphons to slay trolls, and he wants the...",sec={{t="Slaying the Skylords",b="Markhor, a huntsman of Revantusk Village in the Hinterlands, is bitter that the Wildhammer train gryphons to slay trolls. Justice will come for them, he promises, but first he wants you to turn on the elder gryphons of the region, the Skylords. Slay one and return with its plume. The Razorbeak Skylord is a rare breed that tends to keep to the wilds of the Hinterlands, and Markhor blames it for breeding murderous young.",sp=0},{t="The Plume Examined",b="Markhor looks over the plume and wonders aloud how many hunters the beast devoured before it met justice at your hands.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor offers it at Revantusk Village in the Hinterlands.",al={"quest giver","who gives avenging the fallen","markhor location"}},{q="Why does Huntsman Markhor want a Skylord slain?",a="Markhor says the Wildhammer train gryphons to slay trolls, and he wants the elder gryphons of the region, the Skylords, eradicated. He says the Razorbeak Skylord is a rare breed that breeds murderous young.",al={"why kill razorbeak skylord","why kill skylord","why hunt gryphons"}},{q="Where can a Razorbeak Skylord be found?",a="Markhor says this rare breed keeps to the wilds of the Hinterlands.",al={"skylord location","where is razorbeak skylord","skylord plume location"}},{q="What must be brought back to Markhor?",a="Slay a Razorbeak Skylord and return to Markhor with its plume.",al={"what item do i need","avenging the fallen objective","skylord drop"}}},kw={"avenging the fallen","gryphon","hinterlands","huntsman markhor","razorbeak skylord","revantusk village","skylord plume","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",faction="Horde",id=7830},src={"Wowpedia: Avenging the Fallen"}}
E["quest:7839"] = {t="quest",n="Vilebranch Hooligans",z="hinterlands",s="Smith Slagtree of Revantusk Village says Vilebranch trolls invaded the village and stole his tools. He keeps spare tools, but the stolen set was a gift from a kind-hearted gnome who saved his life when he was a young orc, and he wants it back.",h="Smith Slagtree of Revantusk Village says Vilebranch trolls invaded the village and stole his tools.",sec={{t="A Gift From a Gnome",b="Vilebranch trolls invaded Revantusk Village and stole Smith Slagtree's tools. He has backup tools, but the stolen set was a gift from a kind-hearted gnome who saved his life when he was a young orc. He tells you the tools mean the world to him and asks you to recover them.",sp=0},{t="Where the Tools Were Seen",b="Slagtree says Markhor reported seeing the tools near the temples of Agol'watha and Shaol'watha, in the northeast of the Hinterlands. He adds that you should also check Skulk Rock, and warns that the Vilebranch trolls of the region are ruthless and murderous.",sp=0}},faq={{q="Why are these stolen tools so important to Smith Slagtree?",a="The set was a gift from a kind-hearted gnome who saved Slagtree's life when he was a young orc. He has backup tools, but he says these mean the world to him.",al={"why does slagtree care about his tools","slagtree lost tools lore","why are slagtrees tools special"}},{q="Who stole the tools from Revantusk Village?",a="Vilebranch trolls invaded the village and stole Smith Slagtree's tools.",al={"who took the tools","who stole slagtrees tools"}},{q="Where were the missing tools taken?",a="Markhor saw them near the temples of Agol'watha and Shaol'watha, in the northeast of the Hinterlands. Slagtree also says to check Skulk Rock.",al={"where are slagtrees tools","where to find the tools","slagtree tool location"}},{q="Who reported seeing the tools after the raid?",a="Markhor is the one who brought Slagtree word of where the tools were seen.",al={"who saw the tools","who reported the stolen tools"}}},kw={"agol'watha","hinterlands","markhor","revantusk village","shaol'watha","skulk rock","slagtree's lost tools","smith slagtree","vilebranch"},rel={"zone:hinterlands","topic:troll"},m={start="Smith Slagtree",["end"]="Smith Slagtree",level="48",faction="Horde",id=7839},src={"Wowpedia: Vilebranch Hooligans"}}
E["quest:7840"] = {t="quest",n="Lard Lost His Lunch",z="hinterlands",s="Lard, of the village of Revantusk in the Hinterlands, is hungry and frightened. A Vilebranch struck Lard during a private picnic, and Lard fled without lunch. You are asked to fetch it from an island to the north.",h="Lard, of the village of Revantusk in the Hinterlands, is hungry and frightened.",sec={{t="A Picnic Interrupted",b="Lard was picnicking at a secret spot when a Vilebranch, ugly and mean in Lard's telling, hit Lard with a big stick. Lard bolted for Revantusk and left the lunch behind. Now Lard is hungry, and afraid to go back.",sp=0},{t="The Island Northward",b="The picnic spot lies on an island to the north. Lard hopes you will go there, find the lunch and bring it back, taking care around the Vilebranch trolls.",sp=0},{t="Lard's Thanks",b="The lunch turns out to be a huge haunch of meat. Lard wolfs it down, thanks you, and promises you a special picnic basket for your help.",sp=1}},faq={{q="Who is Lard?",a="A resident of Revantusk in the Hinterlands, hungry and frightened after a Vilebranch struck Lard with a big stick.",al={"lard hinterlands","who is lard","lard revantusk"}},{q="Where did Lard lose his lunch?",a="At a hidden picnic spot on an island to the north.",al={"where is lards lunch","lard picnic spot","lards secret spot"}},{q="Why did Lard leave his food behind?",a="A Vilebranch hit Lard with a big stick during the picnic, and Lard ran back to Revantusk without the lunch.",al={"why did lard run","who attacked lard"}},{q="What should you watch out for on the island?",a="Lard names the Vilebranch trolls as the danger on the island.",al={"vilebranch on island","dangers lards island"}}},kw={"hinterlands","island","lard","lunch","picnic","revantusk village","vilebranch"},rel={"zone:hinterlands"},m={start="Lard",["end"]="Lard",level="49",id=7840},src={"Classic quest text: Lard Lost His Lunch"}}
E["quest:7841"] = {t="quest",n="Message to the Wildhammer",z="hinterlands",s="At Revantusk Village in the Hinterlands, Otho Moji'ko says the Wildhammer are striking deals with the trolls' enemies, and this time the high elves are their partners. Otho wants a message sent to the Wildhammer dwarves in the blood of the Highvale high elves at Quel'Danil Lodge.",h="At Revantusk Village in the Hinterlands, Otho Moji'ko says the Wildhammer are striking deals with the trolls'...",sec={{t="A Message in Blood",b="The Wildhammer are forging new alliances with the trolls' enemies, and this time the high elves are their partners. Otho Moji'ko spits at the thought. A message is owed to the dwarves, written in the blood of their new friends: slaughter every Highvale high elf you come across and leave the bodies as a warning. Highvale Outrunners, Scouts, Marksmen and Rangers gather at Quel'Danil Lodge, in the Hinterlands' northwest.",sp=0},{t="Word at Revantusk Village",b="When you return, Otho declares that the Revantusk are forging new alliances as well, and praises your work.",sp=1}},faq={{q="Who offers this quest?",a="Otho Moji'ko, who stands in Revantusk Village.",al={"who gives message to the wildhammer","otho mojiko quest"}},{q="Where are the Highvale high elves located?",a="They gather at Quel'Danil Lodge, in the Hinterlands' northwest.",al={"quel danil lodge location","where are highvale elves","where to find highvale scouts"}},{q="Why does Otho Moji'ko want the high elves attacked?",a="Otho says the Wildhammer are striking deals with the trolls' enemies, and now they are working with the high elves. Otho wants a message sent to the Wildhammer dwarves, written in the blood of the high elves.",al={"why attack quel danil","why kill high elves hinterlands"}},{q="Which Highvale elves does Otho want slaughtered?",a="Highvale Outrunners, Scouts, Marksmen and Rangers at Quel'Danil Lodge.",al={"which highvale elves","highvale marksman","highvale ranger"}}},kw={"highvale","hinterlands","message to the wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},rel={"zone:hinterlands","topic:troll","quest:7842","quest:7843"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7841},src={"Wowpedia: Message to the Wildhammer"}}
E["quest:7842"] = {t="quest",n="Another Message to the Wildhammer",z="hinterlands",s="After the first message, Otho Moji'ko at Revantusk Village says the Wildhammer and their gryphons are as close as a troll and a mate. Disgusting, but it can be used against them. Otho wants gryphons in the Hinterlands killed for their feathers.",h="After the first message, Otho Moji'ko at Revantusk Village says the Wildhammer and their gryphons are as...",sec={{t="A Message of Feathers",b="After the Highvale high elves, Otho Moji'ko has another message to send. The Wildhammer and their gryphons are said to be as close as a troll and a mate, which Otho finds disgusting, but useful. Kill the gryphons you meet across the Hinterlands and collect their Long Elegant Feathers. Gryphons are known to live in every region there. From the feathers, Otho will make the final message.",sp=0},{t="Otho's Pleasure",b="Otho expects the last message to scare the Wildhammer off, or else to make them very, very angry. Otho is delighted that one more step remains before the Wildhammer see that trolls cannot be crossed.",sp=1}},faq={{q="Who gives this quest?",a="Otho Moji'ko, who stands in Revantusk Village.",al={"who gives another message to the wildhammer","another message questgiver","otho mojiko"}},{q="Why does Otho Moji'ko want gryphon feathers?",a="Otho says the Wildhammer and their gryphons are as close as a troll and a mate, and wants to use that against them. The feathers will go into the final message.",al={"why gryphon feathers","why kill gryphons hinterlands"}},{q="Where can gryphons be found?",a="Gryphons are known to live in every region of the Hinterlands.",al={"gryphon locations hinterlands","where are hinterlands gryphons"}},{q="What came before this message?",a="It follows Message to the Wildhammer, in which Otho had Highvale high elves slaughtered as a warning to the dwarves.",al={"what comes before another message to the wildhammer","message to the wildhammer chain"}}},kw={"gryphon","hinterlands","long elegant feather","otho moji'ko","revantusk village","wildhammer"},rel={"quest:7841","quest:7843","zone:hinterlands","topic:troll"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7842},src={"Wowpedia: Another Message to the Wildhammer"}}
E["quest:7843"] = {t="quest",n="The Final Message to the Wildhammer",z="hinterlands",s="Otho Moji'ko gives you a spear soaked in blood and bound with gryphon feathers. You are to take it to Aerie Peak, in the west of the Hinterlands, and drive it into the earth beside the well at the heart of the town.",h="Otho Moji'ko gives you a spear soaked in blood and bound with gryphon feathers.",sec={{t="A Spear for Aerie Peak",b="Following Another Message to the Wildhammer, Otho Moji'ko gives you the final message: a spear soaked in blood and bound with gryphon feathers. Carry it to Aerie Peak and plant it, dead center of town beside the well, to show the dwarves that trolls mean business. Otho hopes you come back alive, and warns of furious Wildhammer dwarves and rowdy Alliance folk.",sp=0},{t="Otho's Hope",b="Otho wishes to have seen the faces of the dwarves, and wonders aloud whether they are packing their bags and leaving town. Otho promises you the big mojo for the deed.",sp=1}},faq={{q="Who sends you to plant the spear?",a="Otho Moji'ko, who stands in Revantusk Village.",al={"quest giver","who gives the quest","otho mojiko"}},{q="Where must the spear be planted?",a="Beside the well at the heart of Aerie Peak, in the west of the Hinterlands.",al={"spear location","where do i place the spear","aerie peak well"}},{q="What is the final message made of?",a="A spear soaked in blood and bound with gryphon feathers.",al={"what is the spear","gryphon feathers spear","the final message item"}},{q="What came before this in the chain?",a="It follows Another Message to the Wildhammer, in which Otho called for gryphon feathers to make this final message.",al={"previous quest","prerequisites","wildhammer message chain"}}},kw={"aerie peak","gryphon feathers","hinterlands","otho moji'ko","revantusk village","spear","wildhammer"},rel={"quest:7842","quest:7841","zone:hinterlands","topic:troll","topic:alliance"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="50",faction="Horde",id=7843},src={"Wowpedia: The Final Message to the Wildhammer"}}
E["quest:7844"] = {t="quest",n="Cannibalistic Cousins",z="hinterlands",s="Mystic Yayo'jin of Revantusk Village calls the Vilebranch trolls a depraved lot who prey on other trolls and humanoids. With Zul'jin not there to destroy them, she asks you to destroy their Scalpers and Soothsayers near the temples in the north by northeast.",h="Mystic Yayo'jin of Revantusk Village calls the Vilebranch trolls a depraved lot who prey on other trolls and...",sec={{t="Three Tribes, One Land",b="Three tribes of trolls live in the Hinterlands, and Mystic Yayo'jin says that apart from being trolls in the same land, they have little in common. She calls the Vilebranch, aptly named, a depraved lot who prey on other trolls and humanoids. Zul'jin would have wiped them out with ease, but Zul'jin is not there, and the Revantusk are left to their own devices.",sp=0},{t="Where the Vilebranch Gather",b="Yayo'jin asks you to destroy the Vilebranch Scalpers and Soothsayers, who are to be found around the Shaol'watha and Agol'watha temples, in the Hinterlands' north by northeast.",sp=0},{t="Yayo'jin's Praise",b="On your return, Yayo'jin declares that even Zul'jin could not have done better.",sp=1}},faq={{q="Who offers this quest?",a="Mystic Yayo'jin, who stands in Revantusk Village.",al={"cannibalistic cousins quest giver","who gives cannibalistic cousins","mystic yayojin"}},{q="Why does Yayo'jin want the Vilebranch destroyed?",a="She calls the Vilebranch a depraved lot who prey on other trolls and humanoids, and says the filth of the region falls to you to destroy.",al={"why revantusk fight vilebranch","vilebranch cannibalism","revantusk vilebranch conflict"}},{q="Where can the Vilebranch trolls be found?",a="Around the Shaol'watha and Agol'watha temples, in the Hinterlands' north by northeast.",al={"shaolwatha location","agolwatha location","where are vilebranch soothsayers"}},{q="Which Vilebranch does Yayo'jin want destroyed?",a="Vilebranch Scalpers and Vilebranch Soothsayers.",al={"cannibalistic cousins targets","who do i kill for cannibalistic cousins"}},{q="Where is Zul'jin?",a="Not in the Hinterlands for now. Yayo'jin says that if Zul'jin were there, he would wipe the Vilebranch out with ease, but he is not, so the Revantusk are left to their own devices.",al={"is zuljin here","where is zuljin hinterlands","zul'jin status"}}},kw={"agol'watha","cannibalistic cousins","mystic yayo'jin","revantusk village","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},rel={"zone:hinterlands","topic:troll"},m={start="Mystic Yayo'jin",["end"]="Mystic Yayo'jin",level="48",faction="Horde",id=7844},src={"Wowpedia: Cannibalistic Cousins"}}
E["quest:7845"] = {t="quest",n="Kidnapped Elder Torntusk!",z="hinterlands",s="Primal Torntusk of Revantusk Village says Vilebranch savages carried off her mate, Elder Torntusk, in a bold midnight raid. Spies say he is alive and held prisoner atop Jintha'alor, and she asks you to save him.",h="Primal Torntusk of Revantusk Village says Vilebranch savages carried off her mate, Elder Torntusk, in a bold...",sec={{t="A Midnight Raid",b="Vilebranch savages struck Revantusk Village at midnight and took Elder Torntusk, mate of Primal Torntusk. Her spies say he is still alive, a prisoner atop Jintha'alor, capital of the Vilebranch in the southern Hinterlands. Primal Torntusk fears the village could not bear losing him.",sp=0},{t="The Faceless Blood God",b="Word is that Vile Priestess Hexx readies the captive for sacrifice to Hakkar, the faceless blood God.",sp=0},{t="Once You Reach Him",b="Reaching the Elder, you are told to move quickly, for the guards surely know of your arrival by now.",sp=1}},faq={{q="Who took Elder Torntusk?",a="Vilebranch savages took him in a bold midnight raid on Revantusk Village.",al={"who kidnapped elder torntusk","who took torntusk","kidnappers of torntusk"}},{q="Where is Elder Torntusk being held?",a="Her spies say he is a prisoner atop Jintha'alor, capital of the Vilebranch in the southern Hinterlands.",al={"elder torntusk location","where is elder torntusk","where is torntusk captive"}},{q="What fate awaits Elder Torntusk atop Jintha'alor?",a="Word is that Vile Priestess Hexx readies him for sacrifice to Hakkar, the faceless blood God.",al={"why was torntusk captured","what do vilebranch want with torntusk","hexx sacrifice torntusk"}},{q="Who is Primal Torntusk?",a="Primal Torntusk is the mate of Elder Torntusk, and she asks you to save him.",al={"who is primal torntusk","primal torntusk mate"}}},kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},rel={"quest:7846","quest:7847","zone:hinterlands"},m={start="Primal Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7845},src={"Wowpedia: Kidnapped Elder Torntusk!"}}
E["quest:7846"] = {t="quest",n="Recover the Key!",z="hinterlands",s="Elder Torntusk is held at Jintha'alor in shackles. He says Hitah'ya the Keeper has the key to his bindings and is in the nearby cave, well guarded, and he asks you to kill her and bring it back.",h="Elder Torntusk is held at Jintha'alor in shackles.",sec={{t="The Keeper's Cave",b="After Kidnapped Elder Torntusk!, you find Elder Torntusk bound in shackles at Jintha'alor. Hitah'ya the Keeper holds the key to his bindings and is in the nearby cave, well guarded. Elder Torntusk asks you to kill her and fetch the key so his shackles come loose, for only then can he go home.",sp=0},{t="Elder Torntusk's Thanks",b="With the key in hand, Elder Torntusk rises to his feet. He thanks you and says the Revantusk will know your deeds.",sp=1}},faq={{q="Who holds the key to Elder Torntusk's shackles?",a="Hitah'ya the Keeper holds the key. Elder Torntusk says she is in the nearby cave and is guarded well.",al={"who has the key","hitahya the keeper","where is the shackle key"}},{q="Where is Elder Torntusk held?",a="Elder Torntusk is held at Jintha'alor.",al={"where is elder torntusk","torntusk location","jintha'alor torntusk"}},{q="Why does Elder Torntusk need the key?",a="The key opens the shackles on his bindings. Only then, he says, will he be free to return home.",al={"why the shackle key","what is the key for"}}},kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recover the key","revantusk","shackle key"},rel={"quest:7845","quest:7847","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7846},src={"Wowpedia: Recover the Key!"}}
E["quest:7847"] = {t="quest",n="Return to Primal Torntusk",z="hinterlands",s="Elder Torntusk asks you to return to his mate, Primal Torntusk, at Revantusk Village and tell her that he is coming home.",h="Elder Torntusk asks you to return to his mate, Primal Torntusk, at Revantusk Village and tell her that he is...",sec={{t="News for His Mate",b="Elder Torntusk is free of his bindings, and he asks you to return to Revantusk Village. There you are to tell his mate, Primal Torntusk, that he is coming home.",sp=0},{t="The Village Is Grateful",b="Primal Torntusk says you have served the Revantusk greatly, and that the village owes you a deep debt of thanks.",sp=1}},faq={{q="Who sends you on this journey?",a="Elder Torntusk asks you to carry the news of his rescue to his mate.",al={"who starts return to primal torntusk","elder torntusk quest giver"}},{q="Where is Primal Torntusk located?",a="Primal Torntusk is at Revantusk Village in the Hinterlands.",al={"where is primal torntusk","primal torntusk location","where to turn in return to primal torntusk"}},{q="What am I supposed to tell Primal Torntusk?",a="That Elder Torntusk is coming home.",al={"what to tell primal torntusk","torntusk message"}},{q="What came before this journey?",a="It follows Recover the Key!, after the earlier effort that began in Kidnapped Elder Torntusk!",al={"previous quest","primal torntusk quest chain"}}},kw={"elder torntusk","hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},rel={"quest:7846","quest:7845","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Primal Torntusk",level="51",faction="Horde",id=7847},src={"Wowpedia: Return to Primal Torntusk"}}
E["quest:7849"] = {t="quest",n="Separation Anxiety",z="hinterlands",s="Huntsman Markhor in Revantusk Village has lost his twin brother Malkhor, taken by the Vilebranch in the same raid that took Torntusk's mate. Malkhor met a swift, brutal end, and his remains were fed to the Vilebranch's oozes and wolves. Markhor says his brother's life is beyond saving, yet his soul can still be rescued, and he asks you to recover the remains.",h="Huntsman Markhor in Revantusk Village has lost his twin brother Malkhor, taken by the Vilebranch in the same...",sec={{t="A Twin's Loss",b="Markhor says that many in the village have lost loved ones to the wilds, and his own loss is Malkhor, his twin. The Vilebranch took Malkhor during the raid that took Torntusk's mate. Malkhor was not fated to live, and his captors put him to a swift, brutal death.",sp=0},{t="Where the Remains Lie",b="The Vilebranch fed what was left of Malkhor to their oozes and wolves. A refuse pit filled with oozes and a wolf den both lie near the top of the temple of Jintha'alor. His bones rest in the midst of a sludge pit close to the top tier, and his skull lies on the top tier itself. Markhor means to carry the remains to Yayo'jin, who will prepare them for a proper burial.",sp=0}},faq={{q="Who was Huntsman Malkhor?",a="Malkhor was the twin brother of Huntsman Markhor. The Vilebranch took him during the raid that also took Torntusk's mate, and put him to a swift, brutal death.",al={"who is malkhor","markhors brother","malkhor lore"}},{q="Where were Malkhor's remains taken?",a="The Vilebranch fed his remains to their oozes and wolves. His skull lies on the top tier of Jintha'alor, and his bones sit in a sludge pit near that top tier.",al={"where are the bones","where is malkhors skull","jintha'alor remains"}},{q="Who will prepare Malkhor for burial?",a="Markhor says he will take the remains to Yayo'jin, who will prepare them for a proper burial.",al={"burial for malkhor","who is yayojin","yayo'jin"}},{q="Why does Markhor need the bones returned?",a="Markhor cannot save his brother's life any more, but he says his brother's soul can still be saved. For that, he wants the remains recovered.",al={"why recover remains","save malkhors soul","saving his soul"}}},kw={"bones","hinterlands","jintha'alor","malkhor","markhor","revantusk","skull","vilebranch","yayo'jin"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="50",faction="Horde",id=7849},src={"Wowpedia: Separation Anxiety (quest)"}}
E["quest:7850"] = {t="quest",n="Dark Vessels",z="hinterlands",s="Primal Torntusk in Revantusk Village says the Vilebranch fight with a supernatural ferocity, the work of Vile Priestess Hexx's foul weavings of magic. Throughout Jintha'alor lie dark vessels of tainted blood, radiating a foul magic that belongs to the faceless blood God. Torntusk asks you to steal them and bring them back, so the taint can be removed.",h="Primal Torntusk in Revantusk Village says the Vilebranch fight with a supernatural ferocity, the work of Vile...",sec={{t="The Vilebranch Fury",b="Wherever you walk in Jintha'alor, you will find vessels of tainted blood. They radiate the dark power of the faceless blood God, which strengthens the Vilebranch and drives them to madness. Torntusk believes that taking the vessels away and removing their taint will loosen the blood God's grip on them.",sp=0},{t="After the Vessels Return",b="With the vessels in hand, the dark energy compelling the Vilebranch is lifted, though only for now. Torntusk reminds you to stay ever vigilant against evil, since a fallen priestess is soon replaced by another.",sp=1}},faq={{q="Who gives the quest Dark Vessels?",a="Primal Torntusk gives it, in Revantusk Village in the Hinterlands.",al={"who gives dark vessels","dark vessels questgiver"}},{q="Where are the tainted vessels located?",a="Dark vessels of tainted blood can be found throughout Jintha'alor in the Hinterlands.",al={"where are dark vessels","vessels of tainted blood location","find tainted blood"}},{q="Why are the Vilebranch trolls so ferocious?",a="Primal Torntusk blames the foul magical weavings of Vile Priestess Hexx. The vessels of tainted blood also carry the power of the faceless blood God, which strengthens the Vilebranch and drives them mad.",al={"why are vilebranch crazy","vilebranch madness","vilebranch ferocity"}},{q="What does Primal Torntusk plan to do with the vessels?",a="Torntusk plans to remove the taint from them, in order to loosen the faceless blood God's grip on the Vilebranch.",al={"why collect the vessels","what happens to the blood vessels"}}},kw={"blood god","dark vessels","jintha'alor","primal torntusk","revantusk village","tainted blood","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Primal Torntusk",["end"]="Primal Torntusk",level="50",faction="Horde",id=7850},src={"Wowpedia: Dark Vessels (Classic)"}}
E["quest:7861"] = {t="quest",n="Wanted: Vile Priestess Hexx and Her Minions",z="hinterlands",s="Primal Torntusk has ordered Vile Priestess Hexx and her minions brought to justice, and a grand prize awaits anyone who slays the priestess and her elite Aman'zasi guard. You will find them atop Jintha'alor in the Hinterlands.",h="Primal Torntusk has ordered Vile Priestess Hexx and her minions brought to justice, and a grand prize awaits...",sec={{t="A Strike at Jintha'alor",b="Primal Torntusk has ordered that Vile Priestess Hexx and her minions be brought to justice. The targets are the priestess herself and the Aman'zasi guards, her elite. Atop Jintha'alor, in the Hinterlands, is where they are found. Once they are slain, you report back to Torntusk at Revantusk Village.",sp=0}},faq={{q="Who posted the bounty for Vile Priestess Hexx?",a="The call to arms was issued by order of Primal Torntusk, and a grand prize is offered to whoever slays the priestess and her guard.",al={"who wants hexx dead","who gave this bounty","priestess hexx quest giver"}},{q="Where can Vile Priestess Hexx and her guards be found?",a="They are found atop Jintha'alor in the Hinterlands.",al={"where is hexx","vile priestess hexx location","amanzasi guards location"}},{q="Who must be slain to fulfill the bounty?",a="The priestess Hexx herself, along with her Aman'zasi elite guard of the Vilebranch.",al={"hexx bounty objectives","who to kill for hexx"}},{q="Where is the bounty turned in?",a="Report to Primal Torntusk at Revantusk Village once the priestess and her guard are slain.",al={"where to turn in hexx bounty","primal torntusk location"}}},kw={"aman'zasi","hexx","hinterlands","jintha'alor","primal torntusk","revantusk village","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7861},src={"Wowpedia: Wanted: Vile Priestess Hexx and Her Minions"}}
E["quest:7862"] = {t="quest",n="Job Opening: Guard Captain of Revantusk Village",z="hinterlands",s="Guard Captain Malkhor has been lost, and Revantusk's guard needs a new captain. Anyone who wants the post must wipe out Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters, then bring an application to Primal Torntusk in the Hinterlands.",h="Guard Captain Malkhor has been lost, and Revantusk's guard needs a new captain.",sec={{t="A Vacant Post",b="A call to arms announces that Guard Captain Malkhor has been lost, so Revantusk's guard has no captain once more. Whoever wants to lead it is invited to do the work set out in the notice and then send an application to Primal Torntusk.",sp=0},{t="Proving Worth",b="An applicant is to exterminate four kinds of Vilebranch: Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters. When that is done, return to Primal Torntusk in Revantusk Village.",sp=0}},faq={{q="Why is the position of Guard Captain open?",a="Guard Captain Malkhor was lost, and the notice says the captaincy of Revantusk is vacant again.",al={"why is guard captain open","what happened to malkhor","who was previous captain"}},{q="Who receives the application once the enemies are slain?",a="Applications go to Primal Torntusk, in Revantusk Village.",al={"who do i turn this in to","where to submit application","who evaluates the applicants"}},{q="Which enemies must be defeated to qualify?",a="Applicants must exterminate Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters.",al={"which vilebranch to kill","job opening targets","who do i kill for guard captain"}}},kw={"berserker","blood drinker","guard captain","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7862},src={"Wowpedia: Job Opening: Guard Captain of Revantusk Village"}}
E["quest:8273"] = {t="quest",n="Oran's Gratitude",z="hinterlands",s="After Rin'ji's Secret, the chain that began with Rin'ji is Trapped! comes to its close with Oran Snakewrithe, to whom you bring a tablet.",h="After Rin'ji's Secret, the chain that began with Rin'ji is Trapped!",sec={{t="A Tablet for Oran",b="Rin'ji is Trapped! began this chain, and Rin'ji's Secret was the step just before this one. Oran Snakewrithe is the one who receives the tablet you carry.",sp=0},{t="Oran's Answer",b="Oran asks where the tablet turned up, and you tell of a small island, deserted, at the Overlook Cliffs. Oran finds this very interesting, puts the tablet carefully away, and says the Dark Lady will be very pleased with the discovery.",sp=1}},faq={{q="Who is Oran Snakewrithe?",a="Oran Snakewrithe is the one who closes the chain that began with Rin'ji is Trapped! and went on through Rin'ji's Secret.",al={"oran","who is oran","oran snakewrithe lore"}},{q="What comes before this in the chain?",a="Before it comes Rin'ji's Secret, and before that Rin'ji is Trapped!.",al={"previous quest","prereq for oran's gratitude","how to start oran's gratitude"}}},kw={"dark lady","hinterlands","oran snakewrithe","overlook cliffs","rin'ji","tablet"},rel={"quest:2782","quest:2742","zone:hinterlands"},m={start="Oran Snakewrithe",["end"]="Oran Snakewrithe",level="47",faction="Horde",id=8273},src={"Oran's Gratitude"}}
E["quest:836"] = {t="quest",n="Rescue OOX-09/HL!",z="hinterlands",s="After the beacon has stirred the fallen homing robot, Oglethorpe Obnoticus speaks from the robot itself. OOX-09/HL needs an open, safe place to begin its take-off, so it is to be escorted to the shoreline beyond Overlook Cliff, and then Oglethorpe waits in Booty Bay.",h="After the beacon has stirred the fallen homing robot, Oglethorpe Obnoticus speaks from the robot itself.",sec={{t="A Walk to the Shore",b="Oglethorpe's voice crackles from the robot again. The machine needs an open, safe place to begin a lengthy take-off procedure, and the shoreline beyond Overlook Cliff will do nicely. Its built-in cloaking cannot be used yet, and Oglethorpe needs time to make it operational again.",sp=0},{t="Word in Booty Bay",b="Once the robot has been brought safely to the shore, Oglethorpe Obnoticus asks you to come and talk in Booty Bay.",sp=0}},faq={{q="Where does the robot need to be escorted?",a="OOX-09/HL is to be taken to the shoreline beyond Overlook Cliff, an open place where it can start its take-off.",al={"where does oox-09 go","hinterlands chicken escort destination","overlook cliff shore"}},{q="Who is responsible for creating this homing robot?",a="The robot is the work of the gnome Oglethorpe Obnoticus, who is in Booty Bay.",al={"who made oox-09","oox creator","who built the chicken"}},{q="Why can't the robot simply take off where it was found?",a="Its take-off procedure is lengthy and needs an open, safe place. Meanwhile Oglethorpe needs time to make its cloaking operational again.",al={"why does the chicken walk","why escort oox-09"}},{q="Where do you go once the escort reaches the shore?",a="Oglethorpe Obnoticus asks to be seen in Booty Bay once the robot is safely at the shore.",al={"where to turn in rescue oox-09","who do i report to","oglethorpe location"}},{q="What came before this escort?",a="It follows Find OOX-09/HL!, in which the distress beacon was carried to the crashed robot.",al={"oox-09 previous quest","prerequisite for rescue oox-09"}}},kw={"booty bay","cloaking","homing robot","oglethorpe obnoticus","overlook cliff","oox-09/hl"},rel={"quest:485","zone:hinterlands","subzone:booty-bay"},m={start="Homing Robot OOX-09/HL",["end"]="Oglethorpe Obnoticus",level="48",id=836},src={"Wowpedia: Rescue OOX-09/HL!"}}
E["zone:hinterlands"] = {t="zone",n="The Hinterlands",z="hinterlands",s="The Hinterlands are a rugged, densely forested wilderness in eastern Lordaeron, tucked between the Plaguelands and the sea. The region is defined by ancient Amani troll temple ruins, the towering aeries of the Wildhammer clan at Aerie Peak, and a colossal Great Tree anchoring a mysterious rift to the Emerald Dream.",h="The Hinterlands are a rugged, densely forested wilderness in eastern Lordaeron, tucked between the...",sec={{t="A Land of Clashing Claims",b="Long before humans or dwarves walked northern Lordaeron, the forest trolls of the Amani Empire held dominion over the Hinterlands. Following their defeat in the ancient Troll Wars, their empire shattered into disparate tribes. Centuries later, after the tragic War of the Three Hammers drove the Wildhammer dwarves from Grim Batol, the dwarves migrated north and made their home on the surface at Aerie Peak. Taming the native gryphons and embracing shamanic traditions, the Wildhammer constructed a massive skybound stronghold. The trolls viewed these surface-dwelling dwarves as unwelcome squatters upon ancestral lands, sparking a ceaseless feud of skirmishes and raids.",sp=0},{t="Tribes of the Forest",b="Three distinct forest troll factions occupy the dense canopy and crumbling stone temples. The brutal and fanatical Vilebranch tribe is the strongest, maintaining sprawling strongholds at the terraced temple-city of Jintha'Alor and the towering Altar of Zul. To the south, the weaker Witherbark tribe clings to Shadra'Alor and Hiri'Watha. The nomadic Revantusk tribe, long scorned by their cousins and lacking a true home, chose a radical path after the Third War: they struck a treaty with Thrall's New Horde. Bolstered by orcish and Forsaken aid, the Revantusk founded Revantusk Village on the eastern sea cliffs, carving out a defiant coastal bastion.",sp=0},{t="The Slumbering Rift",b="In the northern reaches of the Hinterlands stands Seradane, a colossal Great Tree sheltering a portal to the Emerald Dream. Deep within its boughs sits a massive mystical portal opening into the Emerald Dream, guarded by creatures of nature and members of the green dragonflight. However, a creeping shadow known as the Emerald Nightmare has begun to seethe across the portal's threshold, twisting once-benevolent drakes and dragonspawn into furious guardians of the grove.",sp=1}},faq={{q="How do I get to the Hinterlands?",a="Both Alliance and Horde travelers approach from Hillsbrad Foothills, heading northeast through a mountain pass beyond Durnholde Keep. From there, Alliance travelers follow the road to Aerie Peak, while Horde adventurers cross eastward across the wilderness down to Revantusk Village on the eastern coast.",al={"hinterlands entrance","how to enter hinterlands","getting to hinterlands"}},{q="Who rules Aerie Peak?",a="Falstad Wildhammer, Lord of Aerie Peak, leads the Wildhammer clan here. Thane Kurdran Wildhammer led the clan during the Second War.",al={"wildhammer leader","who leads wildhammer","aerie peak ruler"}},{q="Why are the Revantusk trolls allied with the Horde?",a="Unlike the hostile Vilebranch and Witherbark tribes who rejected Horde emissaries, the nomadic Revantusk tribe sought protection and an end to wandering. The New Horde provided vital resources and soldiers to construct Revantusk Village along the coast, winning the tribe's fierce loyalty against local rivals.",al={"revantusk horde","why troll horde hinterlands","revantusk village lore"}},{q="What is Jintha'Alor?",a="Jintha'Alor is a massive, multi-tiered ancient troll fortress carved into the southern cliffs. It serves as the primary bastion of the ruthless Vilebranch tribe, thick with foul sacrificial altars, elite warriors, and witch doctors practicing blood rites in service to their dark loas.",al={"jintha'alor lore","troll city hinterlands","vilebranch city"}},{q="What is the Great Tree at Seradane?",a="Seradane is one of Azeroth's Great Trees, sheltering a portal to the Emerald Dream. Green dragons and wildkin watch over the grove.",al={"seradane portal","big tree hinterlands","green dragon hinterlands"}},{q="What is Quel'Danil Lodge?",a="Quel'Danil Lodge is a forest retreat maintained by Highvale high elves. Spared the Scourge's direct assault on Quel'Thalas, these rangers and scholars cooperate with the neighboring Wildhammer dwarves and share vital intelligence regarding the hostile forest trolls.",al={"high elf lodge hinterlands","queldanil","elves in hinterlands"}}},ang={["race:Dwarf"]="For Wildhammer kin and visiting Bronzebeards alike, Aerie Peak represents dwarven life without stone ceilings—a place of soaring skies, shamanic power, and legendary gryphons.",["race:Troll"]="The Hinterlands hold ancient Amani glory, where bloodlines clash over ancient temple steps and the Revantusk prove that forest trolls have an enduring place within the New Horde.",["faction:Alliance"]="Though the Wildhammer dwarves cherish their fierce independence, aiding their outposts and the high elves of Quel'Danil builds critical goodwill against common troll threats.",["faction:Horde"]="Revantusk Village offers the Horde a vital eastern beachhead in northern Lordaeron, but survival requires beating back the ferocious Vilebranch tribe.",["class:Druid"]="The ancient tree of Seradane holds a deep connection to the Emerald Dream, though the creeping rot of the Nightmare requires close and watchful vigilance."},kw={"aerie peak","gryphon","hinterlands","jintha'alor","quel'danil","revantusk","seradane","vilebranch","wildhammer","witherbark"},rel={"topic:wildhammer-clan","topic:new-horde","topic:emerald-dream","topic:troll","subzone:durnholde-keep","zone:arathi","zone:hillsbrad","zone:westernplaguelands"},src={"Hinterlands"}}
